style.css:
@-moz-document domain("changenow.io") {
html, body {
    background: #1a1a1a;
    color: #fff;
}

/* cards */
.exchange-stepper--panel, .new-stepper-subscription__content, .useful-tips, .new-stepper-telegram-info__content, .often-change__main, .tx-page-finished .tx-page--head-container, .call-to-actions-buttons__item, .tx-page-finished .transaction-details, .tx-page-finished .tx-page--currency-block .amount-bottom .tx-page--currency-block--amount--btn, .tx-page-finished .tx-page__cashback-block, .new-stepper-transaction-id__number {
    background-color: #292929;
}

/* texts */
.transaction-step--get-amount, .transaction-step--recipient-wallet, .transaction-step--refund-address, .useful-tips__item-description, .useful-tips__block-title, .useful-tips__header, p, .new-stepper-subscription__field .new-stepper-field__label, .useful-tips__contact-support-text, .new-stepper-telegram-info__right a, .transaction-step .deposit-info--amount, .transaction-step .deposit-info--address, .transaction-step .deposit-info--extra-id, .new-stepper-subscription__agreement .new-stepper-checkbox__label, .often-change__main-title, .tx-page-finished .tx-page--currency-block--amount .amount-send, .tx-page-finished .transaction-details .transaction-details-header--info--title, .tx-page-finished .transaction-details .transaction-details--exchange-steps .exchange-step-info--title, .tx-page-finished .tx-page__cashback-amount, .exchange-stepper--warning-field-yellow p, .timer__time, .timer__info {
    color: #fff;
}

/* title */
.transaction-step--get-label, .transaction-step--recipient-wallet-label, .transaction-step--refund-address-label {
    color: #808086;
}

/* loading background */
.transaction-step--deposit-info__done::after {
    background-color: rgba(54, 64, 55, .8);
}

.often-change {
    border: 1px solid #7b7b7b;
    background: #FFF;
}

.tx-page-finished .transaction-details .transaction-details-header--info--shared-btn {
    background: #5b5b5b;
}

/* borders */
.tx-page-finished .tx-page__cashback-block, .tx-page-finished .tx-page--currency-block .amount-bottom .tx-page--currency-block--amount--btn, .tx-page-finished .tx-page--currency-block .amount-bottom, .tx-page-finished .tx-page--currency-block--amount {
    border: 1px solid #ffffff42;
}

.cookie-warning__content {
    display: none;
}

/* inputs */
.now-input__light .now-input--input, .combobox__light, .new-stepper-button-lock, .new-stepper-field__input {
    background-color: #302f37;
    color: #dedede;
}

/* inputs borders */
.exchange-calculator__light .exchange-calculator--fields-section__amount, .exchange-calculator__light .exchange-calculator--fields-section__estimation, .new-stepper-field__wrapper-input {
    border: 1px solid #535353;
}

/* inputs borders right */
.exchange-calculator__light .exchange-calculator--amount-field, .exchange-calculator__light .exchange-calculator--estimation-field {
    border-right: 1px solid #5b5b5b;
}

.exchange-stepper__side-block, .deposit-predictions {
    display: none;
}

.currency-item__light .currency-item--ticker {
    color: #dedede;
}

.exchange-calculator__light .exchange-calculator--tab {
    background-color: #302f37;
    color: #dedede;
    border: 1px solid #535353;
}
}
